/* { dg-final { scan-output "Linking AIR to metallib:" } } */
/* { dg-final { set msl_files [glob -nocomplain "*.c.metal"]; if { [llength $msl_files] < 1 } { fail "no Metal (.c.metal) generated by mkoffload" } else { foreach f $msl_files { scan-file $f {#include <metal_stdlib>} ; scan-file $f {kernel void} } } } } */

int
main (void)
{
  int a[128];

  for (int i = 0; i < 128; i++)
    a[i] = i;

#pragma acc parallel loop copy(a)
  for (int i = 0; i < 128; i++)
    a[i] = a[i] + 1;

  return a[0] != 1;
}
